function transformArray(nums) {
  const count = [0, 0];
  for (const num of nums) {
    count[num % 2]++;
  }
  const result = [];
  for (let bit = 0; bit <= 1; bit++) {
    for (let i = 0; i < count[bit]; i++) {
      result.push(bit);
    }
  }
  return result;
}

