function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : int(1, 8);
  // Small inputs are sometimes all even or all odd; otherwise the odd share is random.
  const oddShare = size === 'large' ? rand() : [0, 1, rand()][int(0, 2)];
  const nums = Array.from({ length: n }, () => {
    const half = int(0, 499);
    return rand() < oddShare ? 2 * half + 1 : 2 * half + 2;
  });
  return [nums];
}
